"1a6":"<b>{name} ist vorbei: +{pay}</b><br>Du hast {pct} von dem geliefert, was die Menge wollte.",
"1a7":"<b>{name} startet heute!</b><br>{bw} zusätzliche Nachfrage in {city} für {d} Tage.",
"1a8":"<b>{name} war ein Desaster.</b><br>Nur {pct} geliefert, und es trendete in den sozialen Medien. Vertragsstrafe: {pay}.",
"1a9":"startet in {n} T.",
"1aa":"Eine komplette Netzwerk-Fabric, die in deine Hosentasche passt.",
"1ab":"Großes Shelf, große Reichweite, große Rechnung.",
"1ac":"Kohärentes Pluggable im Router. Kein Transponder-Shelf.",
"1ad":"Elastische Interconnection, jetzt mit Speck. Großgezogen auf einer Farm bei BrisVegas, von dem Typen, der jedes Mal eine Glasfaserfirma gründet, wenn er einen Flat White ausgetrunken hat. Verbindung hochfahren in 59 Sekunden, grunzen in 60.",
"1ae":"Fester Mux plus Verstärker. Bis zu 16 Kanäle, kein Fernschalten.",
"1af":"Volles C-Band, fernkonfigurierbar, nimmt Langstrecken-Transponder. Bis zu 64 Kanäle.",
"1ag":"Beleuchtet auch das L-Band: doppeltes Spektrum, bis zu 128 Kanäle auf einem Faserpaar und Verstärker, deren Erklärung doppelt so lange dauert.",
"1ah":"Stark in Asien und Afrika. Jede Verbindung kommt mit einem Trostpreis.",
"1ai":"Doppelte Geschwindigkeit, kürzere Reichweite.",
"1aj":"Doppelte WaveMagic. Volle Geschwindigkeit nur auf kürzeren Abschnitten, und ein Lüfter, den man vom Parkplatz aus hört.",
