"1b4":"Der Long Tail ({n} kleine Netze)",
"1b5":"Die Netze, für deren Erreichbarkeit du Transit zahlst, die größten zuerst, und der günstigste Weg, jedes davon auf Peering umzustellen. Das ist deine To-do-Liste auf dem Weg zu Tier 1.",
