"1b9":"Waves und Glasfaser",
"1ba":"Wohin das Geld geht",
"1bb":"Woher der Traffic deiner Nutzer kommt und wie er zu dir gelangt. Transit ist der einzige Teil, den du pro Gigabit zahlst; Caches, PNIs und IX-Peering sind kostenlos oder pauschal. Tippe auf eine Spalte zum Sortieren.",
"1bc":"Wen dein Transit trägt",
"1bd":"Entlang der Trasse lebt eine geschützte Hamsterart.",
"1be":"Ein Gemeinderat will eine öffentliche Anhörung. Über die Farbe der Kanaldeckel.",
"1bf":"Archäologen haben auf deiner Trasse ein römisches Badehaus gefunden.",
