"1bl":"<b>Lizenz erteilt!</b><br>Dein Joint Venture darf jetzt POPs in Festlandchina bauen.",
"1bm":"<b>{name} hat gekündigt.</b><br>Zu viele Ausfälle und zu wenig Bandbreite in {city}.",
