"1br":"<b>{net} hat dich am {ix} in {city} de-peert.</b><br>{why} Der Traffic fällt auf deinen nächstbesten Pfad zurück.",
"1bs":"<b>{net} ist dem {ix} beigetreten!</b><br>Noch ein Mitglied, das {fee}/Monat für einen Port zahlt.",
