"1bu":"<b>Behoben: {what}</b><br>{where} läuft wieder normal.",
"1bv":"<b>SLA-Verletzung: {name}.</b><br>Der Angriff auf {city} kam durch, und dein geschützter Kunde ging down. Du schuldest {pen} an SLA-Gutschriften.",
"1bw":"Die Gasleitung von jemand anderem lag genau da, wo laut Plan keine war.",
"1bx":"<b>Die Gefälligkeits-Route ist vorbei.</b><br>Neue Netze, mit denen du nicht verbunden bist, erreichst du jetzt nur noch über dein eigenes Peering und deinen Transit.",
"1by":"Der Bohrtrupp ist auf einen Granitbrocken so groß wie ein Bus gestoßen.",
"1bz":"<b>Das Internet ist zurück.</b><br>Die Hälfte jedenfalls. Alles wurde in Eile gepatcht, und niemand hat etwas gelernt.",
"1c":"Hier stehen deine Server. Jeder Standort braucht einen Weg zum HQ.",
"1c0":"Das Genehmigungsamt hat deine Genehmigung verloren. Und dann den Ersatz.",
"1c1":"Die Bahn hat ihre Meinung zur Grunddienstbarkeit geändert.",
