"1f0":"Faceplant hatte keine Lust mehr auf koreanische Nutzungsgebühren und hat koreanische Nutzer still und leise auf seine Server in Hongkong verschoben. Seiten laden für alle in Seoul im Schneckentempo. Die Regulierungsbehörde entwirft gerade eine Strafe.",
