"1f2":"<b>Glitch verlässt Korea.</b><br>Die Game-Streaming-Seite nennt koreanische Netzgebühren „unerschwinglich teuer“ und macht dort dicht. Ihr Traffic in Seoul halbiert sich, für immer. Lokale Streamer sind schon weitergezogen.",
