"1f9":"<b>Kernschmelze der optischen Control Plane!</b><br>Jede gemietete Wave in {reg} ist gerade auf einen Schlag dunkel geworden. Deine eigene Dark Fiber ist okay. Genau deshalb besitzen Leute Glasfaser.",
