"1i9":"<b>Staubsauger-Vorfall in {city}</b><br>Die Reinigungskraft bei {dc} hat einen deiner Router ausgesteckt, um einen Staubsauger anzuschließen. Der andere lief weiter. Der Boden ist blitzblank.",
"1ia":"Du hast dich beim Kanalplan auf {a}–{b} vertippt und einen neuen Kanal genau über alle bestehenden gelegt.",
"1ib":"Dein Bereitschaftsingenieur hat um 3 Uhr nachts in {city} „clear bgp *“ in Produktion getippt. Es wurde gecleart.",
"1ic":"Deine ROA ist übers Wochenende abgelaufen. Deine Präfixe sind RPKI-invalid, und etwa das halbe Internet verwirft sie.",
"1id":"Dein Router in {city} ist abgestürzt und bootet neu. Er {what}. Bootzeit bei diesem hier: etwa {min} Minuten pro Versuch, und er ist bei Versuch {n}.",
