"1iu":"<b>Die {ship} sticht in See!</b><br>{name}, dein eigenes {km} km langes Kabel von {a} nach {b}. Fertig in etwa {n} Tagen, wenn die Wale mitspielen.",
"1iv":"<b>Diese Optiken brauchen den Regen-Standort.</b><br>Entferne zuerst die Langstreckenkanäle oder behalte den Standort.",
"1iw":"Ein eigenes Faserpaar. Das Glas ist billig, die Technik nicht: Du kaufst ein Line System mit einem Verstärker alle {km} km und dann Optiken für jeden Kanal. Deine Technik kann ausfallen, und du reparierst sie.",
"1ix":"Ein Faserpaar auf {cable}, {km} km. Es teilt sich das Kabel mit den Waves aller anderen, Anker inklusive.",
"1iy":"Selbst bauen <small>{price} · ~{n} Tage</small>",
"1iz":"Dark Fiber über die chinesische Grenze ist nicht zu haben. Kauf stattdessen eine grenzüberschreitende Wave.",
"1j":"Zieh zuerst aus {city} aus.",
"1j0":"Dark Fiber wird ab Kundenlevel 2 freigeschaltet. Du brauchst die Größe, damit sich eigene optische Technik lohnt.",
"1j1":"Zum Vergleich: Eine gemietete 1.6T-Wave kostet auf dieser Strecke {price}/Monat. Optiken kommen als Nächstes, im Link-Panel.",
"1j2":"Von {city}",
"1j3":"<b>{km} km sind länger, als jede Optik mit voller Geschwindigkeit reicht.</b> Transponder laufen im Langstreckenmodus (1.2T, 800G oder 400G pro Kanal), oder du fügst unterwegs Regen-Standorte hinzu, um wieder volle Geschwindigkeit zu bekommen.",
"1j4":"IRU mieten <small>{price}/Monat · fertig in {n} Tagen</small>",
"1j5":"Level {n}",
"1j6":"Keine Dark Fiber innerhalb der VAE. Nur die zwei lizenzierten Betreiber dürfen hier Glasfaser verlegen, und die verkaufen nur Waves.",
"1j7":"Keine Einrichtungsgebühr, live in Minuten, monatlich abgerechnet. Günstiger als eine Wave für kleine Kapazitäten, aber sie läuft über die Fabric von jemand anderem, und diese Fabric kann ausfallen.",
"1j8":"noch kein POP von dir daran",
"1j9":"Hier verkauft niemand Dark Fiber auf einem Seekabel. Subsea-Kapazität gibt es nur als gemietete Waves.",
"1ja":"Niemand verkauft ein Faserpaar über ein Dutzend Grenzen. Zwischen Kontinenten gibt es Kapazität über Land nur als gemietete Waves.",
"1jb":{"one":"Plus {n} Inline-Verstärker ({price} pro Stück, {mo}/Monat für Hüttenmiete und Strom).","other":"Plus {n} Inline-Verstärker ({price} pro Stück, {mo}/Monat für Hüttenmiete und Strom)."},
"1jc":"Remote Peering am {ix} · nicht empfohlen",
"1jd":"IRU unterschreiben",
"1je":"Nach {city}",
"1jf":"Virtuelle Verbindung über eine NNI-Fabric",
"1jg":"Du brauchst zuerst einen Fabric-Port an einem deiner POPs. Öffne den Tab Infra eines POPs und kauf einen Port auf {list}.",
"1jh":"Dein eigener Graben: fast keine Miete, aber Genehmigungen und Graben dauern ewig, und Verzögerungen kommen vor.",
"1ji":"Dein POP · braucht dort einen Fabric-Port",
