"1t9":"Dein Network Operations Center. Jede Benachrichtigung landet auch hier. Im Internet fällt ständig was aus. Dank redundanter Links und mehrerer Upstreams wird der Traffic von selbst umgeleitet.",
"1ta":"Generator mieten",
"1tb":"Eine Brieftaube hat einen deiner Links in einem inoffiziellen Latenztest geschlagen. Die Moral ist am Boden. Der Durchsatz ist okay.",
