"1te":"Eine Schaltsekunde hat einen deiner Router überzeugt, es sei 1970. Die Uptime zeigt jetzt minus 56 Jahre. Der Traffic ist okay.",
"1tf":"Eine Route, die du in Jahr 1 zurückgezogen hast, ist irgendwo im Internet immer noch sichtbar. Niemand weiß, wo. Alles gut. Wahrscheinlich.",
"1tg":"Ein zweistündiges Meeting über Router-Hostnamen endete mit einer Abstimmung für „router-final-v2-NEU“.",
