"2kr":"Ein Community-Exchange, betrieben über einer Cider-Bar. Winzig, günstig, und jedes Mitglied bekommt ein Glas.",
"2ks":"Ein kleinerer kommerzieller Exchange, nur ein Stück die Straße runter von DE-KICKS. Veröffentlicht seine Preise auf einer einzigen Webseite, was DE-KICKS als Kriegserklärung betrachtet. Ports gibt es ohne Vertriebs-Webinar.",
"2kt":"Dicht, sättigend und sehr günstig.",
"2ku":"Zu jeder Session gibt es eine Kaffeepause. Wird streng durchgesetzt.",
"2kv":"Gegrillte Ports, serviert mit Senf und einem kalten Bier.",
"2kw":"Vom Platzhirsch im Labor gezüchtet. Die eigene Familie ist drauf; alle anderen zahlen fürs Zuschauen.",
"2kx":"Geschichtet, robust und irgendwie immer geöffnet.",
"2ky":"Viele kleine Sessions auf kleinen Tellern.",
"2kz":"Gehört den Mitgliedern und ist gemeinnützig. Kleiner als LYNX, aber bei der Mitgliederversammlung gibt es Kekse.",
"2l":"Der CFO hat den Stecker gezogen. Vielleicht eine günstigere Form?",
"2l0":"Mumbais Streetfood-Exchange. Schnell, scharf und günstig.",
"2l1":"Eine Fabric quer durchs ganze Land. Verteilt, günstig und ein bisschen selbstgefällig.",
"2l2":"Offen belegt, günstig und um 3 Uhr nachts zu haben.",
"2l3":"Öffnet um sechs, Snacks gratis, schließt, wenn die letzte Session fällt.",
"2l4":"Betrieben von Hackern auf Koffein. Der Route Server hat eine Discokugel.",
"2l5":"Settlement-free Peering mit friesischen Wurzeln. Die 10G- und 100G-Ports kosten nichts. Bring eine ASN und Appetit auf Route Server mit. Mayonnaise kostet extra.",
"2l6":"In irgendeiner Garage gestartet, wie alles andere hier in der Gegend.",
"2l7":"Stark, süß und günstiger als der Platzhirsch.",
"2l8":"Dauert ewig beim Einrichten, macht aber sehr satt.",
"2l9":"Der Herausforderer. Jeden Morgen frisch, am Abend etwas altbacken.",
"2la":"Der Herausforderer von IX Straya. Taucht am Rand jeder Stadt auf, auch dort, wo sich sonst niemand die Mühe macht. Gewöhnungsbedürftig, wie Vegemite.",
"2lb":"Der Herausforderer der DE-KICKS-Fabric, eingewickelt und zum Mitnehmen.",
"2lc":"Der alteingesessene Madrider Exchange. Neutrale Interconnection, lokales Flair und ein Route Server, der nie Siesta macht.",
"2ld":"Der ältere Exchange in Johannesburg, betrieben vom lokalen ISP-Verband. Vor jedem Wartungsfenster auf Holz klopfen.",
"2le":"Die ganze Nachbarschaft trägt das Haus gemeinsam. Kostenlos dabei, mit dem Segen der Regierung.",
"2lf":"Tokio hat mehr Exchanges, als irgendwer aufzählen kann. Diesen hier hat ein Breitbandriese gegründet, und er kommt ordentlich verpackt, jedes Mitglied in seinem eigenen Fach.",
"2lg":"Warschau hat mehr Exchanges, als irgendwer zählen kann. Das hier ist der zweitgrößte, diese Woche.",
"2lh":"Man sieht die Fabric nicht, aber sie ist definitiv da.",
"2li":"<b>Auto-TE ist live.</b><br>Der Controller schiebt Überlauf jetzt auf Ausweichpfade, sobald der kürzeste voll ist.",
