"2qm":"Ein Pfad von Marseille nach Singapur, und 80 Gbps zwischen Asien und dem Rest deines Netzes, 30 Tage am Stück",
"2qn":"Amsterdam, Hosting-Hauptstadt Europas, mitten in der Botnetz-Hochsaison. Jeder smarte Toaster, jedes Babyfon und jeder ungepatchte Kühlschrank der Welt hat sich für eine Seite entschieden, und es ist nicht deine. Alle paar Tage eine Flut, immer mehr davon im Terabit-Bereich, während auch alles andere weiter kaputtgeht. Du startest mit größerer Hardware freigeschaltet, und die wirst du brauchen.",
"2qo":"Breitband in Sydney, Melbourne, Brisbane, Adelaide und Perth, zwei verschiedene Kabel nach Übersee, und 500 Gbps bedient",
"2qp":"Vom Kap nach Kairo",
"2qq":"Kapstadt. Bau ein Netz quer durch Afrika: Jede Grenze will ihre eigene Genehmigung, und die Hälfte der Stromnetze ist nicht auf deiner Seite.",
"2qr":"Cogentle und Goggle reden nicht miteinander, und diesmal für immer. Kauf den billigen Transit, wenn du dich traust.",
"2qs":"Bogotá, Lima, Santiago und São Paulo mit Panama-Stadt verbunden, und 150 Gbps bedient",
"2qt":"Liefere den Karneval vollständig aus",
"2qu":"Jedes Kabel durchs Rote Meer ist gekappt, und der Hop nach Ägypten auch. Bring Marseille trotzdem mit Singapur ins Gespräch: um Afrika herum, über Land oder andersherum um den Planeten.",
