"2qz":"Halte 20 Fluten, 5 davon über 1 Tbps: jedes Ziel bei 97 % oder besser, sonst niemand betroffen",
"2r":"Röhren über Plan",
"2r0":"Honolulu, mitten im Pazifik. Die Kabel zwischen Amerika, Asien und Australien sind so lang, dass eine Wave darauf nur 400G oder 800G trägt. Halte das Licht auf einer Insel an, starte es neu, und jeder Hop wird kürzer und schneller. Du startest mit freigeschalteter 1.6T-Hardware.",
"2r1":"Mittelatlantischer Akzent",
"2r2":"Nur Spätzle-IX",
"2r3":"Ordnung und Fortschritt",
"2r4":"Ponta Delgada auf den Azoren, mitten im Atlantik. Florida–Spanien ist einfach zu lang für eine 1.6T-Wave: direkt hinüber trägt sie nur 1.2T. Lande auf den Inseln dazwischen, starte das Licht neu, und jeder Hop läuft mit 1.6T oder besser. Lissabon–Lagos schafft 1.6T am Stück, aber teuer: über die Kanaren ist es billiger. Du startest mit freigeschalteter 1.6T-Hardware.",
"2r5":"Ports an 15 IX.brrr-Exchanges, die dein Backbone mit São Paulo verbindet, einer davon in Manaus, und 200 Gbps bedient",
"2r6":"Erreiche 50 % des Internets und bediene 300 Gbps",
"2r7":"Krise im Roten Meer",
"2r8":"Rio, ganz von vorn. Der Karneval beginnt in 90 Tagen und will fünf Tage am Stück 400 Gbps. Die ganze Welt schaut zu.",
"2r9":"<b>Sandbox-Modus</b><br>Eine Milliarde Dollar und alles freigeschaltet. Chaos: {chaos}. Bau das Internet, das du immer wolltest, und halt einen Ersatzbagger bereit.",
"2ra":"<b>Sandbox-Modus</b><br>Eine Milliarde Dollar, alles freigeschaltet, und nichts geht jemals kaputt. Bau das Internet, das du schon immer wolltest.",
"2rb":"São Paulo. Brasilien ist ein Kontinent: vierzig IX.brrr-Exchanges, Tausende Provedores und der Amazonas zwischen dir und dem Norden.",
"2rc":"Seoul, wo der Sender zahlt. Jedes Gbps, das ein Carrier nach Korea liefert, kostet dich zusätzlich zur Transitrechnung eine Sender-pays-Gebühr, die drei Platzhirsche reden nur über einen bezahlten PNI, Gigabit für zu Hause kostet so viel wie ein Bibimbap, und koreanische Nutzer merken jede Millisekunde. Transit in Tokio ist billig, wenn deine Kunden die Reise aushalten.",
"2rd":"{g} Gbps ausgeliefert, Seoul gut versorgt ({q} %), 99 % Reichweite und ein Monatsgewinn",
"2re":"Haisaison: Seekabelschnitte doppelt so wahrscheinlich",
"2rf":"Start in Panama-Stadt. Über Land kommt nichts durch den Darién Gap, und die Anden stehen allem anderen im Weg.",
"2rg":"Start in Stuttgart, wo niemand Transit verkauft. Erreiche das Internet nur über Peering, PNIs, Caches und deine eigene Glasfaser. Kein Transit, nirgends, niemals.",
"2rh":"Start mit nur $100k",
"2ri":"Sydney, 2013. Die Toilet Paper Group hat ihre eigene Glasfaser in die Keller von Wohnhäusern verlegt, und das nationale Netz hat „Rosinenpickerei“ geschrien. Du bist dran: Lass das Nearly Broadband Network links liegen, zahl die Abgabe und sei als Erster da.",
