"rf":"Remote Peering am IX",
"rg":"Im Moment ist {city} ein einziges Gebäude. Ein Stromausfall, eine kaputte Klimaanlage oder eine Reinigungskraft mit Staubsauger legt die ganze Stadt lahm, und ein zweiter Router hilft da nicht. Ein zweites Rechenzentrum am anderen Ende der Stadt, verbunden über deinen eigenen Metro-Ring, hält den halben POP am Laufen.",
