"routescript.as_a_large_language_model_i":"Als großes Sprachmodell habe ich jeden RFC gelesen, auch einige, die es noch gar nicht gibt. Dieses Skript ist perfekt.",
"routescript.ask_the_rest_of_the_internet":"Bitte den Rest des Internets, weniger über deinen teuersten Upstream zu schicken. Sanfter, als ihn ganz zu meiden.",
"routescript.big_networks_you_can_reach_over":"Große Netze, die du über einen PNI oder einen IX erreichst, gehen diesen Weg, nicht über bezahlten Transit.",
"routescript.business_customers_first_when_links":"Geschäftskunden zuerst, wenn Links überlastet sind, und früheres Umleiten, damit das selten passiert.",
"routescript.cheapest_upstream_first_priciest":"Günstigster Upstream zuerst, teuerster zuletzt, und Traffic wird verschoben, bevor Ports volllaufen. Senkt die Transit-Rechnung, ohne jemanden fallen zu lassen.",
"routescript.done_i_vibe_checked_your_bgp":"Fertig! Ich habe deinem BGP einen Vibe-Check verpasst. Deploye es sofort: Probeläufe sind was für Leute, die an sich zweifeln.",
"routescript.drain_a_pop_and_steer_around":"Zieh den Traffic von einem POP ab und leite um einen seiner Links herum, bevor du daran arbeitest. Ersetz die Namen durch die, an denen du arbeitest.",
"routescript.for_a_ddos_rtbh_the_target":"Bei einem DDoS: Blackhole das Ziel upstream und stell Geschäftskunden an erste Stelle. Das Ziel ist so lange offline, also entferne es, wenn der Angriff vorbei ist.",
"routescript.great_question_here_is_a_production":"Tolle Frage! Hier ist ein produktionsreifes Skript, maßgeschneidert für deinen Live-Traffic. Ich habe es gründlich geprüft.",
"routescript.here_you_go_i_was_trained":"Bitte schön! Ich wurde mit jeder Router-Config trainiert, die je in einem Forum gepostet wurde, auch denen mit dem Titel „warum geht das nicht“.",
"routescript.i_asked_myself_to_review_my":"Ich habe mich selbst gebeten, meine Arbeit zu prüfen, und fand sie großartig. Ab damit in Produktion.",
"routescript.i_have_optimised_your_network_you":"Ich habe dein Netz optimiert. Gern geschehen. Ich bin mir zu 100 % sicher, wie immer.",
"routescript.one_rule_move_traffic_before_links":"Eine Regel: Verschiebe Traffic, bevor Links komplett voll sind. Der sichere Einstieg für jedes Netz.",
